-- Default-off candidate: requires provider ACK, readback and D1 fencing.
CREATE TABLE personal_historical_fast_receipts (
  operation_token TEXT PRIMARY KEY,
  spreadsheet_id TEXT NOT NULL,
  sheet_name TEXT NOT NULL,
  personal_use_id TEXT NOT NULL,
  metadata_id INTEGER NOT NULL,
  source_version INTEGER NOT NULL,
  source_revision INTEGER NOT NULL,
  source_fingerprint TEXT NOT NULL,
  cutover_generation TEXT NOT NULL,
  baseline_json TEXT NOT NULL,
  evidence_digest TEXT NOT NULL CHECK(length(evidence_digest)=64 AND evidence_digest NOT GLOB '*[^0-9a-f]*'),
  created_at TEXT NOT NULL
);
CREATE TRIGGER personal_historical_fast_receipt_validate BEFORE INSERT ON personal_historical_fast_receipts
WHEN NOT EXISTS(SELECT 1 FROM personal_historical_enrollment_intents i JOIN personal_raw_enrollment_locks l ON l.spreadsheet_id=i.spreadsheet_id AND l.sheet_name=i.sheet_name AND l.personal_use_id=i.personal_use_id AND l.metadata_id=i.metadata_id AND l.operation_token=i.operation_token AND l.outer_token=i.outer_token AND l.cutover_generation=i.cutover_generation AND l.state='HELD' WHERE i.spreadsheet_id=NEW.spreadsheet_id AND i.sheet_name=NEW.sheet_name AND i.personal_use_id=NEW.personal_use_id AND i.metadata_id=NEW.metadata_id AND i.source_version=NEW.source_version AND i.source_revision=NEW.source_revision AND i.source_fingerprint=NEW.source_fingerprint AND i.cutover_generation=NEW.cutover_generation AND i.operation_token=NEW.operation_token AND i.baseline_json=NEW.baseline_json AND i.state='IN_FLIGHT') OR NOT EXISTS(SELECT 1 FROM personal_historical_atomic_assertions x WHERE x.assertion_id=NEW.operation_token AND x.ok=1) OR NOT EXISTS(SELECT 1 FROM admin_audit a WHERE a.action='HISTORICAL_ENROLLMENT_VERIFIED' AND a.entity_key=NEW.personal_use_id AND CASE WHEN json_valid(a.after_json) THEN json_extract(a.after_json,'$.operationToken')=NEW.operation_token AND json_extract(a.after_json,'$.evidenceDigest')=NEW.evidence_digest ELSE 0 END )
BEGIN SELECT RAISE(ABORT,'HISTORICAL_FAST_RECEIPT_INVALID'); END;
CREATE TRIGGER personal_historical_fast_receipt_no_delete BEFORE DELETE ON personal_historical_fast_receipts BEGIN SELECT RAISE(ABORT,'HISTORICAL_FAST_RECEIPT_IMMUTABLE'); END;
CREATE TRIGGER personal_historical_fast_receipt_no_update BEFORE UPDATE ON personal_historical_fast_receipts BEGIN SELECT RAISE(ABORT,'HISTORICAL_FAST_RECEIPT_IMMUTABLE'); END;
CREATE TRIGGER personal_historical_fast_receipt_no_replace BEFORE INSERT ON personal_historical_fast_receipts WHEN EXISTS(SELECT 1 FROM personal_historical_fast_receipts r WHERE r.rowid=NEW.rowid OR r.operation_token=NEW.operation_token) BEGIN SELECT RAISE(ABORT,'HISTORICAL_FAST_RECEIPT_IMMUTABLE'); END;
DROP TRIGGER personal_historical_identity_transition;
CREATE TRIGGER personal_historical_identity_transition BEFORE UPDATE OF state ON personal_historical_enrollment_intents
WHEN OLD.state IS NOT NEW.state AND NOT (OLD.state='IN_FLIGHT' AND NEW.state='REVIEW') AND NOT (OLD.state='REVIEW' AND NEW.state='VERIFIED' AND EXISTS(
 SELECT 1 FROM personal_historical_recovery_actions a JOIN personal_raw_enrollment_locks l ON l.spreadsheet_id=a.spreadsheet_id AND l.sheet_name=a.sheet_name AND l.personal_use_id=a.personal_use_id AND l.metadata_id=a.metadata_id AND l.operation_token=a.operation_token AND l.outer_token=a.outer_token AND l.state='REVIEW'
 JOIN owner_personal_transactions p ON p.personal_use_id=a.personal_use_id AND p.version=a.source_version AND p.status='CONFIRMED'
 JOIN personal_projection_source_revisions r ON r.personal_use_id=p.personal_use_id AND r.revision=a.source_revision AND r.state='TRACKED'
 JOIN personal_projection_cutovers c ON c.spreadsheet_id=a.spreadsheet_id AND c.sheet_name=a.sheet_name AND c.generation=a.cutover_generation AND c.state='ACTIVE'
 JOIN personal_legacy_writer_gates g ON g.spreadsheet_id=c.spreadsheet_id AND g.sheet_name=c.sheet_name AND g.generation=c.generation AND g.state='HOLD'
 WHERE a.spreadsheet_id=OLD.spreadsheet_id AND a.sheet_name=OLD.sheet_name AND a.personal_use_id=OLD.personal_use_id AND a.metadata_id=OLD.metadata_id AND a.source_version=OLD.source_version AND a.source_revision=OLD.source_revision AND a.source_fingerprint=OLD.source_fingerprint AND a.cutover_generation=OLD.cutover_generation AND a.operation_token=OLD.operation_token AND a.outer_token=OLD.outer_token AND a.state='APPROVED' AND a.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND EXISTS(SELECT 1 FROM personal_historical_atomic_assertions x WHERE x.assertion_id=a.action_id AND x.ok=1) AND EXISTS(SELECT 1 FROM admin_audit audit WHERE audit.action='HISTORICAL_RECOVERY_APPLIED' AND audit.entity_key=a.personal_use_id AND CASE WHEN json_valid(audit.after_json) THEN json_extract(audit.after_json,'$.actionId')=a.action_id ELSE 0 END )
)) AND NOT (OLD.state='IN_FLIGHT' AND NEW.state='VERIFIED' AND EXISTS(SELECT 1 FROM personal_historical_fast_receipts r JOIN personal_raw_identity_intents j ON j.spreadsheet_id=r.spreadsheet_id AND j.sheet_name=r.sheet_name AND j.personal_use_id=r.personal_use_id AND j.metadata_id=r.metadata_id AND j.state='VERIFIED' AND j.projected_version=r.source_version AND j.projected_revision=r.source_revision AND j.baseline_json=r.baseline_json AND j.verified_evidence_digest=r.evidence_digest AND j.verified_outer_token=OLD.outer_token AND j.verified_generation=r.cutover_generation JOIN personal_historical_atomic_assertions x ON x.assertion_id=r.operation_token AND x.ok=1 JOIN admin_audit a ON a.action='HISTORICAL_ENROLLMENT_VERIFIED' AND a.entity_key=r.personal_use_id AND CASE WHEN json_valid(a.after_json) THEN json_extract(a.after_json,'$.operationToken')=r.operation_token AND json_extract(a.after_json,'$.evidenceDigest')=r.evidence_digest ELSE 0 END WHERE r.spreadsheet_id=OLD.spreadsheet_id AND r.sheet_name=OLD.sheet_name AND r.personal_use_id=OLD.personal_use_id AND r.metadata_id=OLD.metadata_id AND r.operation_token=OLD.operation_token AND r.cutover_generation=OLD.cutover_generation AND r.source_version=OLD.source_version AND r.source_revision=OLD.source_revision AND r.source_fingerprint=OLD.source_fingerprint AND r.baseline_json=OLD.baseline_json)) BEGIN SELECT RAISE(ABORT,'HISTORICAL_RECOVERY_REQUIRED'); END;
DROP TRIGGER personal_enrollment_lock_no_delete;
CREATE TRIGGER personal_enrollment_lock_no_delete BEFORE DELETE ON personal_raw_enrollment_locks WHEN NOT EXISTS(SELECT 1 FROM personal_historical_recovery_actions a JOIN personal_historical_enrollment_intents i ON i.spreadsheet_id=a.spreadsheet_id AND i.sheet_name=a.sheet_name AND i.personal_use_id=a.personal_use_id AND i.metadata_id=a.metadata_id AND i.source_version=a.source_version AND i.source_revision=a.source_revision AND i.source_fingerprint=a.source_fingerprint AND i.cutover_generation=a.cutover_generation AND i.operation_token=a.operation_token AND i.outer_token=a.outer_token AND i.state='VERIFIED' JOIN owner_personal_transactions p ON p.personal_use_id=i.personal_use_id AND p.version=i.source_version AND p.status='CONFIRMED' JOIN personal_projection_source_revisions r ON r.personal_use_id=p.personal_use_id AND r.state='TRACKED' AND r.revision=i.source_revision JOIN personal_projection_admissions d ON d.personal_use_id=i.personal_use_id AND d.sequence=i.admission_sequence JOIN personal_projection_cutovers c ON c.spreadsheet_id=i.spreadsheet_id AND c.sheet_name=i.sheet_name AND c.generation=i.cutover_generation AND c.admission_watermark=i.admission_watermark AND c.state='ACTIVE' JOIN personal_legacy_writer_gates g ON g.spreadsheet_id=c.spreadsheet_id AND g.sheet_name=c.sheet_name AND g.generation=c.generation AND g.state='HOLD' JOIN sheet_metadata_identity_registry m ON m.spreadsheet_id=i.spreadsheet_id AND m.sheet_name=i.sheet_name AND m.metadata_id=i.metadata_id AND m.entity_kind='PERSONAL_USE' AND m.entity_id=i.personal_use_id WHERE OLD.state='REVIEW' AND a.spreadsheet_id=OLD.spreadsheet_id AND a.sheet_name=OLD.sheet_name AND a.personal_use_id=OLD.personal_use_id AND a.metadata_id=OLD.metadata_id AND a.operation_token=OLD.operation_token AND a.outer_token=OLD.outer_token AND a.cutover_generation=OLD.cutover_generation AND a.state='APPROVED' AND a.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND EXISTS(SELECT 1 FROM personal_historical_atomic_assertions x WHERE x.assertion_id=a.action_id AND x.ok=1) AND EXISTS(SELECT 1 FROM admin_audit audit WHERE audit.action='HISTORICAL_RECOVERY_APPLIED' AND audit.entity_key=a.personal_use_id AND CASE WHEN json_valid(audit.after_json) THEN json_extract(audit.after_json,'$.actionId')=a.action_id ELSE 0 END )) AND NOT EXISTS(SELECT 1 FROM personal_enrollment_recovery_actions a JOIN personal_raw_identity_intents i ON i.spreadsheet_id=a.spreadsheet_id AND i.sheet_name=a.sheet_name AND i.personal_use_id=a.personal_use_id AND i.metadata_id=a.metadata_id AND i.state='VERIFIED' AND i.verified_outer_token=a.outer_token AND i.verified_generation=a.cutover_generation AND i.verified_evidence_digest=a.evidence_digest JOIN personal_projection_runtime_intents o ON o.spreadsheet_id=a.spreadsheet_id AND o.personal_use_id=a.personal_use_id AND o.source_version=a.source_version AND o.source_revision=a.source_revision AND o.operation_token=a.outer_token AND o.cutover_generation=a.cutover_generation AND o.state='VERIFIED' AND o.evidence_digest=a.evidence_digest WHERE a.spreadsheet_id=OLD.spreadsheet_id AND a.sheet_name=OLD.sheet_name AND a.personal_use_id=OLD.personal_use_id AND a.metadata_id=OLD.metadata_id AND a.operation_token=OLD.operation_token AND a.outer_token=OLD.outer_token AND a.cutover_generation=OLD.cutover_generation AND a.state='APPROVED' AND a.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND EXISTS(SELECT 1 FROM owner_personal_transactions p JOIN personal_projection_source_revisions r ON r.personal_use_id=p.personal_use_id AND r.state='TRACKED' AND r.revision=a.source_revision WHERE p.personal_use_id=a.personal_use_id AND p.version=a.source_version AND p.status='CONFIRMED') AND EXISTS(SELECT 1 FROM sync_jobs s WHERE s.entity_type='PERSONAL_USE' AND s.entity_key=a.personal_use_id AND s.entity_version=a.source_version AND s.status='COMPLETED') AND EXISTS(SELECT 1 FROM personal_projection_generation_jobs q WHERE q.spreadsheet_id=a.spreadsheet_id AND q.cutover_generation=a.cutover_generation AND q.personal_use_id=a.personal_use_id AND q.source_version=a.source_version AND q.source_revision=a.source_revision AND q.state='COMPLETED')) AND NOT (OLD.state='HELD' AND EXISTS(SELECT 1 FROM personal_historical_fast_receipts r JOIN personal_raw_identity_intents j ON j.spreadsheet_id=r.spreadsheet_id AND j.sheet_name=r.sheet_name AND j.personal_use_id=r.personal_use_id AND j.metadata_id=r.metadata_id AND j.state='VERIFIED' AND j.projected_version=r.source_version AND j.projected_revision=r.source_revision AND j.baseline_json=r.baseline_json AND j.verified_evidence_digest=r.evidence_digest AND j.verified_outer_token=OLD.outer_token AND j.verified_generation=r.cutover_generation JOIN personal_historical_atomic_assertions x ON x.assertion_id=r.operation_token AND x.ok=1 JOIN admin_audit a ON a.action='HISTORICAL_ENROLLMENT_VERIFIED' AND a.entity_key=r.personal_use_id AND CASE WHEN json_valid(a.after_json) THEN json_extract(a.after_json,'$.operationToken')=r.operation_token AND json_extract(a.after_json,'$.evidenceDigest')=r.evidence_digest ELSE 0 END WHERE r.spreadsheet_id=OLD.spreadsheet_id AND r.sheet_name=OLD.sheet_name AND r.personal_use_id=OLD.personal_use_id AND r.metadata_id=OLD.metadata_id AND r.operation_token=OLD.operation_token AND r.cutover_generation=OLD.cutover_generation AND EXISTS(SELECT 1 FROM personal_historical_enrollment_intents i WHERE i.spreadsheet_id=r.spreadsheet_id AND i.sheet_name=r.sheet_name AND i.personal_use_id=r.personal_use_id AND i.metadata_id=r.metadata_id AND i.operation_token=r.operation_token AND i.state='VERIFIED'))) BEGIN SELECT RAISE(ABORT,'PERSONAL_ENROLLMENT_REVIEW_REQUIRED'); END;
